    rule 20 {
        destination {
            address 10.100.93.13/32
            port 9090
        }
        protocol tcp
        set {
            table 102
        }
    }
}

	}
}
table inet mangle {
	chain FORWARD {
		type filter hook forward priority mangle; policy accept;
	}
}
table ip raw {
	chain VYOS_TCP_MSS {
		type filter hook postrouting priority raw; policy accept;
	}

	chain vyos_global_rpfilter {
		return
	}

	chain vyos_rpfilter {
		type filter hook prerouting priority raw; policy accept;
		counter packets 80 bytes 14606 jump vyos_global_rpfilter
	}
--
	}
}
table ip vyos_mangle {
	chain VYOS_PBR_PREROUTING {
		type filter hook prerouting priority mangle; policy accept;
		iifname "eth0" counter packets 15 bytes 864 jump VYOS_PBR_UD_PBR-EGRESS
	}

	chain VYOS_PBR_POSTROUTING {
		type filter hook postrouting priority mangle; policy accept;
	}

	chain VYOS_PBR_UD_PBR-EGRESS {
		ip daddr 10.100.93.13 tcp dport 8080 counter packets 5 bytes 300 meta mark set 0x7fffff9a return comment "ipv4-route-PBR-EGRESS-10"
		ip daddr 10.100.93.13 tcp dport 9090 counter packets 10 bytes 564 meta mark set 0x7fffff99 return comment "ipv4-route-PBR-EGRESS-20"
	}
}
table ip6 vyos_mangle {
	chain VYOS_PBR6_PREROUTING {
		type filter hook prerouting priority mangle; policy accept;
	}

	chain VYOS_PBR6_POSTROUTING {
		type filter hook postrouting priority mangle; policy accept;
	}
}

table inet firewalld { # progname firewalld
	flags owner,persist

	chain mangle_PREROUTING {
		type filter hook prerouting priority mangle + 10; policy accept;
		jump mangle_PREROUTING_ZONES
	}

	chain mangle_PREROUTING_POLICIES_pre {
		jump mangle_PRE_policy_allow-host-ipv6
	}

	chain mangle_PREROUTING_ZONES {
		iifname "eth1" goto mangle_PRE_public
		iifname "eth0" goto mangle_PRE_public
		goto mangle_PRE_public
	}

	chain mangle_PREROUTING_POLICIES_post {
	}

	chain nat_PREROUTING {
		type nat hook prerouting priority dstnat + 10; policy accept;
		jump nat_PREROUTING_ZONES
	}

	chain nat_PREROUTING_POLICIES_pre {
		jump nat_PRE_policy_allow-host-ipv6
	}

	chain nat_PREROUTING_ZONES {
		iifname "eth1" goto nat_PRE_public
		iifname "eth0" goto nat_PRE_public
		goto nat_PRE_public
	}

	chain nat_PREROUTING_POLICIES_post {
	}

	chain nat_POSTROUTING {
		type nat hook postrouting priority srcnat + 10; policy accept;
		jump nat_POSTROUTING_ZONES
	}

	chain nat_POSTROUTING_POLICIES_pre {
	}

	chain nat_POSTROUTING_ZONES {
		oifname "eth1" goto nat_POST_public
		oifname "eth0" goto nat_POST_public
		goto nat_POST_public
	}

	chain nat_POSTROUTING_POLICIES_post {
	}

	chain nat_OUTPUT {
		type nat hook output priority dstnat + 10; policy accept;
		jump nat_OUTPUT_POLICIES_pre
		jump nat_OUTPUT_POLICIES_post
	}

	chain nat_OUTPUT_POLICIES_pre {
	}

	chain nat_OUTPUT_POLICIES_post {
	}

	chain filter_PREROUTING {
		type filter hook prerouting priority filter + 10; policy accept;
		icmpv6 type { nd-router-advert, nd-neighbor-solicit } accept
		meta nfproto ipv6 fib saddr . mark . iif oif missing drop
	}

	chain filter_INPUT {
		type filter hook input priority filter + 10; policy accept;
		ct state { established, related } accept
		ct status dnat accept
		iifname "lo" accept
		ct state invalid drop

	ct state invalid drop
	jump filter_INPUT_ZONES
	reject with icmpx admin-prohibited
}

chain filter_FORWARD {
	type filter hook forward priority filter + 10; policy accept;
	ct state { established, related } accept
	ct status dnat accept
	iifname "lo" accept
	ct state invalid drop
	ip6 daddr { ::/96, ::ffff:0.0.0.0/96, 2002::/24, 2002:a00::/24, 2002:7f00::/24, 2002:a9fe::/32, 2002:ac10::/28, 2002:c0a8::/32, 2002:e000::/19 } reject with icmpv6 addr-unreachable
	jump filter_FORWARD_ZONES
	reject with icmpx admin-prohibited
}

chain filter_OUTPUT {
	type filter hook output priority filter + 10; policy accept;
	ct state { established, related } accept
	oifname "lo" accept
	ip6 daddr { ::/96, ::ffff:0.0.0.0/96, 2002::/24, 2002:a00::/24, 2002:7f00::/24, 2002:a9fe::/32, 2002:ac10::/28, 2002:c0a8::/32, 2002:e000::/19 } reject with icmpv6 addr-unreachable
	jump filter_OUTPUT_POLICIES_pre
	jump filter_OUTPUT_POLICIES_post
}

chain filter_INPUT_POLICIES_pre {
	jump filter_IN_policy_allow-host-ipv6
}

chain filter_INPUT_ZONES {
	iifname "eth1" goto filter_IN_public
	iifname "eth0" goto filter_IN_public
	goto filter_IN_public
}

chain filter_INPUT_POLICIES_post {
}

chain filter_FORWARD_POLICIES_pre {
}

chain filter_FORWARD_ZONES {
	iifname "eth1" goto filter_FWD_public
	iifname "eth0" goto filter_FWD_public
	goto filter_FWD_public
}

chain filter_FORWARD_POLICIES_post {
}

chain filter_OUTPUT_POLICIES_pre {
}

chain filter_OUTPUT_POLICIES_post {
}

chain filter_IN_public {
	jump filter_INPUT_POLICIES_pre
	jump filter_IN_public_pre
	jump filter_IN_public_log
	jump filter_IN_public_deny
	jump filter_IN_public_allow
	jump filter_IN_public_post
	jump filter_INPUT_POLICIES_post
	meta l4proto { icmp, ipv6-icmp } accept
	reject with icmpx admin-prohibited
}

chain filter_IN_public_pre {
}

chain filter_IN_public_log {
}

chain filter_IN_public_deny {
}

